 #!/bin/bash #=============================================================================== #!# script: spark_s3_analyze.sh #!# version: v0.1 #!# #!# Process Spark (YARN container's logs) to retrieve S3 metrics #=============================================================================== #?# #?# usage: ./spark_s3_analyze.sh &lt;S3_LOG&gt; &lt;S3_INPUT&gt; &lt;S3_OUTPUT&gt; #?# #?# S3_LOG Amazon EMR S3 Log Path #?# S3_INPUT S3 path of the input data #?# S3_OUTPUT S3 path of the output data #?# #=============================================================================== RED='\033[0;31m' NC='\033[0m' s3_logs=&quot;$1&quot; input_path=&quot;$2&quot; output_path=&quot;$3&quot; # dowload and decompress logs tmp_path=$(mktemp -d) cd $tmp_path &amp;&amp; aws s3 sync $s3_logs . gzip -d */*.gz echo -e &quot;# ${RED}Application Time${NC}
&quot; completed=$( grep -Ri &quot;Final app status&quot; *001/stderr | awk '{split($0,a,&quot; &quot;); print a[2]}' ) started=$( grep -Ri &quot;ApplicationAttemptId:&quot; *001/stderr | awk '{split($0,a,&quot; &quot;); print a[2]}' ) start=$(echo $started | awk -F: '{ print ($1 * 3600) + ($2 * 60) + $3 }') end=$(echo $completed | awk -F: '{ print ($1 * 3600) + ($2 * 60) + $3 }') duration=$(($end - $start)) elapsed=$(TZ=UTC0 printf '%(%H:%M:%S)T
' $duration) echo &quot;Started : $started&quot; echo &quot;Completed : $completed&quot; echo &quot;Elapsed : $elapsed ($duration sec)&quot; echo echo -e &quot;# ${RED}Get S3 requests count${NC}
&quot; grep -Rh &quot;Executing request&quot; * | awk '{split($0,a,&quot; &quot;); print a[7]}' | \ sort | uniq -c echo echo -e &quot;# ${RED}S3 Input Path${NC}
&quot; echo -e &quot;Path: $input_path
&quot; aws s3 ls $input_path --recursive --summarize --human-readable | grep &quot;Total&quot; | \ sed 's/^ *//; s/ *$//; /^$/d' echo echo -e &quot;# ${RED}S3 Output Path${NC}
&quot; echo -e &quot;Path: $output_path
&quot; aws s3 ls $output_path --recursive --summarize --human-readable | grep &quot;Total&quot; | \ sed 's/^ *//; s/ *$//; /^$/d' echo echo -e &quot;# ${RED}S3 Requests x second (${NC}Top 10${RED})${NC}
&quot; grep -Rh &quot;Executing request&quot; * | awk '{split($0,a,&quot; &quot;); print a[2]}' | \ sort | uniq -c | sort -n | tail -n 10 cd rm -rf $tmp_path
